def transform(g):
    from collections import Counter
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    out=[row[:] for row in g]
    colors=set(x for r in g for x in r)-{bg}
    for col in colors:
        pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==col]
        rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        # verify closed rectangle border
        if not all(g[r][c]==col for r in range(r0,r1+1) for c in range(c0,c1+1) if r in(r0,r1) or c in(c0,c1)):
            continue
        area=(r1-r0-1)*(c1-c0-1)
        fill=7 if area%2==1 else 2
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                out[r][c]=fill
    return out

